import{c as e,J as a,h as o,k as s}from"./chunks/framework.WgZQdPFo.js";const u=JSON.parse('{"title":"Capital Dashboard (Net Worth)","description":"Consolidated Net Worth command center combining personal holdings and workshop business capital across all workspaces.","frontmatter":{"title":"Capital Dashboard (Net Worth)","description":"Consolidated Net Worth command center combining personal holdings and workshop business capital across all workspaces.","order":21},"headers":[],"relativePath":"docs/spaces/moy-kapital/dashboard.md","filePath":"docs/spaces/moy-kapital/dashboard.md"}'),r={name:"docs/spaces/moy-kapital/dashboard.md"};function n(l,t,i,d,c,h){return a(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="capital-dashboard-net-worth" tabindex="-1">Capital Dashboard (Net Worth) <a class="header-anchor" href="#capital-dashboard-net-worth" aria-label="Permalink to &quot;Capital Dashboard (Net Worth)&quot;">​</a></h1><p>The <strong>Capital Dashboard</strong> is your high-level command center in the My Capital workspace. It aggregates financial data from every corner of the OmniCraft ERP ecosystem to provide an unambiguous answer to a vital question: <strong>what is the true combined value of your business and personal holdings right now?</strong></p><hr><h2 id="consolidated-net-worth-formula" tabindex="-1">Consolidated Net Worth Formula <a class="header-anchor" href="#consolidated-net-worth-formula" aria-label="Permalink to &quot;Consolidated Net Worth Formula&quot;">​</a></h2><p>Your total <strong>Net Worth</strong> is calculated using an exhaustive mathematical formula:</p><p>$$\\text{Net Worth} = \\text{Liquid Accounts} + \\text{Investment Portfolio} + \\text{Property} + \\sum \\text{Workshop Capital}$$</p><p>The dashboard displays four core components:</p><ol><li><strong>Liquid Capital:</strong> readily available funds across all checking accounts, cards, deposits, and stablecoins, converted to your base currency.</li><li><strong>Investment Capital:</strong> market value of your securities, crypto assets, loans, and equity positions net of initial invested principal ($P&amp;L$).</li><li><strong>Physical Assets:</strong> market valuation of long-term equipment, vehicles, real estate, and tools adjusted for ownership percentage.</li><li><strong>Workshop Business Capital:</strong> total enterprise value across all active workspaces: $$\\text{Workshop Capital} = \\text{Cash Flow (DDS)} + \\text{Raw Materials (MAC)} + \\text{Work in Progress} + \\text{Finished Goods (FIFO)}$$</li></ol><div class="info custom-block"><p class="custom-block-title">Instant Multi-Workspace Consolidation</p><p>If you operate three independent businesses (e.g., a leather workshop, a digital pattern store, and craft masterclasses), the dashboard automatically inspects each SQLite database file and compiles their net capital without requiring manual switching between workspaces.</p></div><hr><h2 id="tracking-unallocated-workshop-expenses" tabindex="-1">Tracking Unallocated Workshop Expenses <a class="header-anchor" href="#tracking-unallocated-workshop-expenses" aria-label="Permalink to &quot;Tracking Unallocated Workshop Expenses&quot;">​</a></h2><p>The bottom section of the dashboard features the Balance Delta analysis card, reconciling figures for any selected month:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Metric</th><th style="text-align:left;">Data Source</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Total Inflows</strong></td><td style="text-align:left;">Workshop net profit + business dividends + external income</td></tr><tr><td style="text-align:left;"><strong>Capital Delta</strong></td><td style="text-align:left;">$\\text{Net Worth}<em>{\\text{end}} - \\text{Net Worth}</em>{\\text{start}}$</td></tr><tr><td style="text-align:left;"><strong>Unallocated Personal Expenses</strong></td><td style="text-align:left;">$\\text{Inflows} - \\text{Capital Delta}$</td></tr></tbody></table><p>If the workshops generated $$3,000$ in combined net profit while your consolidated Net Worth increased by $$1,200$, the system deduces that $$1,800$ was spent on everyday family and living expenses.</p><p>You no longer need to track every grocery receipt: the balance delta handles personal expense accounting automatically and down to the cent.</p>',15)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
